import java.security.MessageDigest;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.digest.DigestUtils;

public class Hashes {
    static String hashPassword(String password) throws Exception {
        // ruleid: no-weak-password-hashing-java
        MessageDigest md = MessageDigest.getInstance("MD5");
        return md.digest(password.getBytes()).toString();
    }

    static String sign(String data, byte[] key) throws Exception {
        // ruleid: no-weak-password-hashing-java
        Mac mac = Mac.getInstance("HmacSHA1");
        mac.init(new SecretKeySpec(key, "HmacSHA1"));
        return mac.doFinal(data.getBytes()).toString();
    }

    static String token(String password) {
        // ruleid: no-weak-password-hashing-java
        return DigestUtils.sha1Hex(password);
    }

    static void warmUp() throws Exception {
        // ruleid: no-weak-password-hashing-java
        MessageDigest.getInstance("sha1");
    }

    static String hashSafely(String data) throws Exception {
        // ok: no-weak-password-hashing-java
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return md.digest(data.getBytes()).toString();
    }

    static String configured(String data) throws Exception {
        // ok: no-weak-password-hashing-java
        MessageDigest md = MessageDigest.getInstance(System.getenv("HASH_ALG"));
        return md.digest(data.getBytes()).toString();
    }

    static String signSafely(byte[] key, String data) throws Exception {
        // ok: no-weak-password-hashing-java
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(key, "HmacSHA256"));
        return mac.doFinal(data.getBytes()).toString();
    }
}
